    for(const auto &c:ownedCases) {
        std::string current=ownedSource+(c.resources?resourceSource:"")+(c.resources>=3?extraResourceSource:"");
        if(c.resources>=3) {
            const std::string forage="number_of_objects 12";
            current.replace(current.find(forage),forage.size(),"number_of_objects 3");
        }
        if(c.resources && c.resources%2==0) current.replace(current.find("<CLIFF_GENERATION>"),18,
            "<CLIFF_GENERATION> min_number_of_cliffs 20 max_number_of_cliffs 20 min_length_of_cliff 30 max_length_of_cliff 40");
        check(script.load(0,[&](int32_t id,std::vector<uint8_t> &out) {
            if(id) return false;out.assign(current.begin(),current.end());return true;
        },{},&error),error.c_str());
        rng=c.seed;check(generateRmsMap(script,{},120,120,assets.dat(),rng,map,&error,2,{c.first,c.second}),error.c_str());
        check(map.ownedObjects.size()==10 && map.objects.empty() && map.resourcesAfterOwned.size()==(c.resources?(c.resourceCount?c.resourceCount:77u):0u),"cliff startup has original owned units and resource counts");
        uint32_t hash=2166136261u,terrainHash=2166136261u,nextId=0;
        auto mix=[&](uint32_t id,int owner,int unit,int facet,float x,float y) {
            for(uint32_t v:{id,uint32_t(owner),uint32_t(unit),uint32_t(facet),uint32_t(x*2),uint32_t(y*2)}) hash=(hash^v)*16777619u;
        };
        for(const auto &o:map.cliffs) {mix(o.creationOrdinal,0,o.unit,o.facet,o.x,o.y);nextId=o.creationOrdinal+1;}
        for(const auto &o:map.scenery) {check(o.alive,"cliff startup retains original live trees");mix(nextId++,0,o.unitId,o.facet,o.x,o.y);}
        const uint32_t ownedBase=nextId;
        for(const auto &o:map.ownedObjects) mix(nextId++,o.owner,o.unitId,o.facet,o.x,o.y);
        for(const auto &o:map.resourcesAfterOwned) mix(nextId++,0,o.unitId,o.facet,o.x,o.y);
        for(auto tile:map.terrain) terrainHash=(terrainHash^tile)*16777619u;
        check(rng==c.rng && hash==c.objects && terrainHash==c.terrain && nextId==c.last+1 &&
            map.cliffs.size()+map.scenery.size()+map.ownedObjects.size()+map.resourcesAfterOwned.size()==c.count,
            "original cliff/forest/owned startup records, foundations, allocation gaps and RNG");
        rng=c.seed;check(game.initRms(script,{},120,rng,&error,2,{c.first,c.second}),error.c_str());
        check(rng==c.rng && game.activeObjectCount()==c.count,"native owned cliff startup count/RNG");
        for(size_t i=0;i<map.ownedObjects.size();++i) {
            const auto &o=map.ownedObjects[i];const auto &pose=c.poses[i];const uint32_t id=ownedBase+uint32_t(i)+1;
            const auto &unit=assets.dat().civs[o.civilization].units[o.unitId];
            const auto *graphic=assets.dat().graphic(unit.standingGraphic[0]);
            const bool animated=(graphic->sequenceType&1)!=0;
            const float delay=animated?pose.hold-graphic->frameDuration:0;
            const int frame=animated?pose.frame:0;
            check(o.pendingFoundation==pose.pending && o.animationFrame==frame &&
                std::abs(o.initialIdleDelay-delay)<.00001f,"original owned cliff startup foundation and animation phase");
            const auto position=game.objectPosition(id),animation=game.objectAnimationForTesting(id);
            // Original civ8 adds15 worker HP in the later civilization-bonus pass.
            const float health=pose.hp+(o.civilization==8 && (o.unitId==83 || o.unitId==293)?15.f:0.f);
            check(game.objectUnitId(id)==o.unitId && game.objectPlayer(id)==o.owner && position[0]==o.y && position[1]==120-o.x &&
                game.objectHitPoints(id)==health &&
                game.pendingFoundationForTesting(id)==pose.pending && animation[0]==frame*graphic->frameDuration &&
                std::abs(animation[1]-delay)<.00001f,"native original starting IDs, positions, health and pose");
        }
        uint32_t resourceId=ownedBase+uint32_t(map.ownedObjects.size())+1;
        for(const auto &o:map.resourcesAfterOwned) {
            const auto position=game.objectPosition(resourceId);
            check(game.objectUnitId(resourceId)==o.unitId && game.objectPlayer(resourceId)==0 &&
                position[0]==o.y && position[1]==120-o.x,"original resource IDs and positions after cliff replacements and owned startup");
            ++resourceId;
        }
        for(const auto &pose:gaiaPoses) if(pose.mode==c.resources && pose.seed==c.seed) {
            const uint32_t first=ownedBase+uint32_t(map.ownedObjects.size());
            check(pose.id>=first && pose.id-first<map.resourcesAfterOwned.size(),"original animated Gaia allocation is retained");
            const auto &o=map.resourcesAfterOwned[pose.id-first];
            const auto *graphic=assets.dat().graphic(assets.dat().civs[0].units[o.unitId].standingGraphic[0]);
            const auto animation=game.objectAnimationForTesting(pose.id+1);
            check(o.unitId==pose.unit && o.animationFrame==pose.frame &&
                std::abs(o.initialIdleDelay+graphic->frameDuration-pose.hold)<.00001f &&
                game.objectHitPoints(pose.id+1)==pose.hp && animation[0]==pose.frame*graphic->frameDuration &&
                std::abs(animation[1]-o.initialIdleDelay)<.00001f,"original Gaia animation frames, holds and health");
        }
        const int resourceIds[]={4,11,21,37,40,98,164,165};
        for(int owner:{1,2}) {
            const auto &resources=originalResources[(owner==1?c.first:c.second)-1];
            const int civ=owner==1?c.first:c.second;
            // The configured RMS oracle precedes the full civilization-bonus pass.
            check(game.populationUsedForTesting(owner)==resources[1] &&
                game.populationCapacityForTesting(owner)==(civ==5?200.f:resources[0]+resources[1]),
                "original cliff startup grants and native civilization population bonus");
            for(size_t i=1;i<8;++i)
                check(game.resource(owner,resourceIds[i])==resources[i],"original cliff startup research, population and cost bookkeeping");
        }
        check(game.spawnObjectForTesting(1,83,1,2.5f,2.5f)==c.last+2,"native next allocation retains original cliff replacement gaps");
    }
    check(script.load(0,[&](int32_t id,std::vector<uint8_t> &out) {
        if(id) return false;out.assign(ownedSource.begin(),ownedSource.end());return true;
    },{},&error),error.c_str());
    const auto retainedCount=game.activeObjectCount();
    for(const auto &civs:std::vector<std::vector<uint16_t>>{{0,1},{1,9},{}}) {
        rng=1;
        check(!game.initRms(script,{},120,rng,&error,2,civs) && rng==1 && game.activeObjectCount()==retainedCount,
            "invalid owned cliff civilizations preserve the current world");
    }
    rng=1;
    check(!game.initRms(script,{"FIXED_POSITIONS"},120,rng,&error,2,{1,1}) && rng==1 && game.activeObjectCount()==retainedCount,
        "unverified owned cliff fixed positions preserve the current world");

